import json, os, re
ROOT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..')
def w(p,o):
    p=os.path.join(ROOT,p); os.makedirs(os.path.dirname(p),exist_ok=True); json.dump(o,open(p,'w',encoding='utf-8'),ensure_ascii=False,indent=2)
decks=[]
def deck(did,title,desc,level,cards,tags):
    out=[]
    for n,c in enumerate(cards,1):
        c=dict(c); c["id"]=f"{did}-{n:03d}"; c["tags"]=tags; out.append(c)
    w(f"dane/fiszki/{did}.json",{"version":1,"id":did,"title":title,"description":desc,"level":level,"cards":out})
    decks.append({"id":did,"title":title,"description":desc,"level":level,"file":f"{did}.json","count":len(out)})
def cl(text,hint,note=None):
    d={"type":"cloze","text":text,"hint":hint}
    if note: d["note"]=note
    return d
def ty(front,acc,back=None,hint=None):
    d={"type":"typed","front":front,"accepted":acc,"back":back or acc[0]}
    if hint: d["hint"]=hint
    return d
def ba(front,back,note=None):
    d={"type":"basic","front":front,"back":back}
    if note: d["note"]=note
    return d

