w("dane/fiszki/index.json",{"version":1,"decks":decks})
# walidacja
ids=set()
for d in decks:
    data=json.load(open(os.path.join(ROOT,"dane/fiszki",d["file"]),encoding="utf-8"))
    for c in data["cards"]:
        assert c["id"] not in ids; ids.add(c["id"])
        if c["type"]=="cloze":
            m=re.findall(r"\{\{([^}]+)\}\}",c["text"]); assert len(m)==1,(c["id"],c["text"])
        elif c["type"]=="typed": assert c["accepted"],c["id"]
        elif c["type"]=="basic": assert c["front"] and c["back"]
print(len(decks),"talii,",len(ids),"kart")
